;(function () {
  var formatter = new Intl.RelativeTimeFormat('en')
  var cases = [
    ['RelativeTimeFormat.format(-0)', -0, '0 days ago'],
    ['RelativeTimeFormat.format(0)', 0, 'in 0 days'],
    ['RelativeTimeFormat.format(positive decimal)', 1234.5, 'in 1,234.5 days'],
    ['RelativeTimeFormat.format(rounding carry)', 1.9996, 'in 2 days'],
    ['RelativeTimeFormat.format(large)', 1e21, 'in 1,000,000,000,000,000,000,000 days'],
  ]
  var sink = ''
  function run(f, n) {
    var start = __now()
    for (var i = 0; i < n; i++) sink = f()
    return __now() - start
  }
  for (var c = 0; c < cases.length; c++) {
    var entry = cases[c]
    var f = (function (value) { return function () { return formatter.format(value, 'day') } })(entry[1])
    if (f() !== entry[2]) throw new Error('Wrong result: ' + entry[0])
    var n = 1
    while (n < 10000000 && run(f, n) < 50) n *= 2
    var samples = []
    for (var r = 0; r < 7; r++) samples.push(run(f, n) * 1000 / n)
    samples.sort(function (a, b) { return a - b })
    print(JSON.stringify({name: entry[0], us: samples[3], iterations: n, value: entry[2]}))
  }
  if (sink === undefined) throw new Error('unused result')
})()
